def decide(trace):
    from specflow.refmodel.temporal import after, eventually, edges, worst

    # Activation (from normalized): cmd in {0,1,2,3} while ena==1
    def applies(r):
        return r["inputs"].get("ena") == 1 and r["inputs"].get("cmd") in (0, 1, 2, 3)

    # Helpers to build predicates from dicts (copying normalized style)
    def _holds(cond):
        def p(row):
            for k, v in cond.items():
                val = row["outputs"].get(k, row["inputs"].get(k))
                if val != v:
                    return False
            return True
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Window close: cmd_ack == 1
    until = _any([{"cmd_ack": 1}])
    # Aborts: al==1 or nReset==0 or rst==1
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])

    follows = True  # from normalized.activation.effect_follows

    # Open windows for each entered sequence; closes on cmd_ack, aborts on aborts
    windows = after(trace, applies, until=until, aborts=aborts)
    if not windows:
        return (None, None, 'the activation never occurred: no START/STOP/READ/WRITE while ena==1')

    # Find all edges where either control line changed value
    scl_changes = set(edges(trace, "scl_oen", "change"))
    sda_changes = set(edges(trace, "sda_oen", "change"))
    changed_edges = scl_changes | sda_changes

    # Requirement (transcribed conservatively): each active sequence must drive
    # the open-drain controls -> observe at least one transition on scl_oen or sda_oen
    verdicts = [
        eventually(w, (lambda ce: (lambda r: r["edge"] in ce))(changed_edges),
                   after_activation=follows, strong=True)
        for w in windows
    ]

    return worst(verdicts)

def decide(trace):
    # Derive activation windows from the observed signature: any change of
    # scl_oen or sda_oen is taken as the start of a command-sequence window.
    # The expectation (from the normalized block) is that during those
    # command-sequence windows the module's drive outputs (scl_o, sda_o) remain 0
    # and are not driven high by the module.

    # Find edges where scl_oen or sda_oen changed (compare to previous row).
    opens = []
    prev = None
    for r in trace:
        if prev is not None:
            prev_scl_oen = prev['outputs'].get('scl_oen')
            prev_sda_oen = prev['outputs'].get('sda_oen')
            cur_scl_oen = r['outputs'].get('scl_oen')
            cur_sda_oen = r['outputs'].get('sda_oen')
            if cur_scl_oen != prev_scl_oen or cur_sda_oen != prev_sda_oen:
                opens.append(r['edge'])
        prev = r

    # No activation observed: the command-sequence windows did not occur in this trace.
    if not opens:
        return (None, None, 'the activation never occurred: no scl_oen or sda_oen transitions observed')

    # For each activation, inspect the window from that opening row to the end
    # (TO_END). Assert throughout the window that scl_o==0 and sda_o==0.
    failures = []
    for open_edge in opens:
        # find index of the row that opened this window
        idx = None
        for i, r in enumerate(trace):
            if r['edge'] == open_edge:
                idx = i
                break
        if idx is None:
            # should not happen, but be robust
            continue
        window = trace[idx:]
        violated = False
        for row in window:
            scl_o = row['outputs'].get('scl_o', 0)
            sda_o = row['outputs'].get('sda_o', 0)
            # The requirement forbids the module from driving these signals high.
            if scl_o != 0 or sda_o != 0:
                violated = True
                failures.append((False, row['edge'],
                                 f'output driven high in window opened at edge {open_edge}: scl_o={scl_o} sda_o={sda_o}'))
                break
        if not violated:
            failures.append((True, None, f'window opened at edge {open_edge} held scl_o and sda_o at 0'))

    # worst: any False trumps True; if any failure present return first False
    for v in failures:
        if v[0] is False:
            return v
    # All windows passed
    return (True, None, f'all {len(failures)} command-sequence window(s) showed scl_o and sda_o held low (open-drain drive only)')

def decide(trace):
    """
    Decide REQ-0034: when scl_oen/sda_oen changes the corresponding scl_o/sda
    must be driven 0 if the enable is 0, and released (1) if the enable is 1.

    Returns (ok, edge, detail) where ok is True/False/None per the framework.
    """
    if not trace or len(trace) < 2:
        return (None, None, 'no transitions observed')

    aborted_only = True
    seen_activation = 0

    for i in range(1, len(trace)):
        prev = trace[i-1]
        cur = trace[i]

        # skip rows where an abort (reset) is asserted at the activation
        if cur.get('inputs', {}).get('nReset') == 0 or cur.get('inputs', {}).get('rst') == 1:
            # if the enable changed here it is an aborted activation; record but do not decide
            enable_changed = False
            if prev.get('outputs', {}).get('scl_oen') is not None and cur.get('outputs', {}).get('scl_oen') is not None:
                if prev['outputs'].get('scl_oen') != cur['outputs'].get('scl_oen'):
                    enable_changed = True
            if prev.get('outputs', {}).get('sda_oen') is not None and cur.get('outputs', {}).get('sda_oen') is not None:
                if prev['outputs'].get('sda_oen') != cur['outputs'].get('sda_oen'):
                    enable_changed = True
            if enable_changed:
                # this activation was aborted by reset; continue scanning
                continue

        # check for changes of scl_oen and sda_oen between prev and cur
        checks = []  # list of tuples (line_name, enable_val, line_val)

        if prev.get('outputs', {}).get('scl_oen') is not None and cur.get('outputs', {}).get('scl_oen') is not None:
            if prev['outputs'].get('scl_oen') != cur['outputs'].get('scl_oen'):
                seen_activation += 1
                aborted_only = False
                checks.append(('scl_o', cur['outputs'].get('scl_oen'), cur['outputs'].get('scl_o')))

        if prev.get('outputs', {}).get('sda_oen') is not None and cur.get('outputs', {}).get('sda_oen') is not None:
            if prev['outputs'].get('sda_oen') != cur['outputs'].get('sda_oen'):
                seen_activation += 1
                aborted_only = False
                checks.append(('sda_o', cur['outputs'].get('sda_oen'), cur['outputs'].get('sda_o')))

        # For each enable that changed, the corresponding line must match the mapping:
        # enable 0 -> line driven low (0)
        # enable 1 -> line released/high (1)
        for line, enable_val, line_val in checks:
            # If either value is missing from the row, we cannot decide here
            if enable_val is None or line_val is None:
                return (None, cur.get('edge'), f'missing port value at edge {cur.get("edge")}')

            expected = 0 if enable_val == 0 else 1
            if line_val != expected:
                return (False, cur.get('edge'), f"{line}=={line_val} but expected {expected} when corresponding enable is {enable_val} at edge {cur.get('edge')}")

    if seen_activation == 0:
        return (None, None, 'no enable assert/deassert transitions observed')
    if aborted_only:
        return (None, None, 'all observed enable transitions were aborted by reset')

    return (True, None, f'{seen_activation} enable transition(s) observed and matched the required line values')

def decide(trace):
    """
    Decide REQ-0062: when cmd==2 && ena==1 (STOP) the controller must: sda_oen change, then scl_oen change, then sda_oen change again while scl_oen stays at the post-change value, and then assert cmd_ack (cmd_ack==1).

    Implementation notes:
    - Uses only declared ports. Does not assume numeric meaning for sda_oen/scl_oen; uses transitions as the signature of drive/release.
    - activation.effect_follows is honoured: the effects are searched for after the activation row.
    - Windows aborted by nReset==0 or rst==1 are ignored (treated as unknown). A window that runs to the end without a cmd_ack is unknown.
    - Returns (ok, edge, detail) where edge is the trace row edge that localises the verdict.
    """
    def get_val(row, name):
        # outputs take precedence; inputs only if output not present
        return row['outputs'].get(name, row['inputs'].get(name))

    def is_activation_row(row):
        return row['inputs'].get('cmd') == 2 and row['inputs'].get('ena') == 1

    def is_abort_row(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    n = len(trace)
    windows = []  # each: dict(start=i, end=j or None, aborted=bool)
    i = 0
    while i < n:
        r = trace[i]
        if is_activation_row(r) and (i == 0 or not is_activation_row(trace[i-1])):
            # found a rising activation at i
            aborted = False
            j = None
            k = i + 1
            while k < n:
                if is_abort_row(trace[k]):
                    aborted = True
                    break
                # close when cmd_ack == 1 (normalized until)
                if trace[k]['outputs'].get('cmd_ack') == 1:
                    j = k
                    break
                k += 1
            windows.append({'start': i, 'end': j, 'aborted': aborted})
            # resume scanning after this attempt opened (overlap not allowed)
            i = k + 1
        else:
            i += 1

    # Keep only completed, non-aborted windows (those with end != None and not aborted)
    completed = [w for w in windows if (not w['aborted']) and (w['end'] is not None)]
    if not completed:
        # no completed STOP activation observed in this trace (either none or only aborted/incomplete)
        return (None, None, 'no completed STOP activation (cmd==2 && ena==1 that closed with cmd_ack==1) was observed')

    # Analyze each completed window; any failure is a failing verdict (first fail returned)
    for w in completed:
        start = w['start']
        end = w['end']
        # per normalized.activation.effect_follows == true, search starts after activation row
        search_from = start + 1
        if search_from >= n:
            return (None, trace[start]['edge'], 'activation at end of trace; effects cannot be observed')

        # find first sda_oen transition after activation
        sda1 = None
        for t in range(search_from, end + 1):
            if get_val(trace[t], 'sda_oen') != get_val(trace[t-1], 'sda_oen'):
                sda1 = t
                break
        if sda1 is None:
            return (False, trace[start]['edge'], 'STOP did not show an initial sda_oen transition')

        # find scl_oen transition after sda1
        scl_t = None
        scl_post_val = None
        for t in range(sda1 + 1, end + 1):
            if get_val(trace[t], 'scl_oen') != get_val(trace[t-1], 'scl_oen'):
                scl_t = t
                scl_post_val = get_val(trace[t], 'scl_oen')
                break
        if scl_t is None:
            return (False, trace[sda1]['edge'], 'STOP did not show a scl_oen transition after the initial sda_oen transition')

        # find second sda_oen transition after scl_t
        sda2 = None
        for t in range(scl_t + 1, end + 1):
            if get_val(trace[t], 'sda_oen') != get_val(trace[t-1], 'sda_oen'):
                sda2 = t
                break
        if sda2 is None:
            return (False, trace[scl_t]['edge'], 'STOP did not show a second sda_oen transition after scl_oen release')

        # verify that at the time of the second sda_oen transition, scl_oen equals the post-change value
        if get_val(trace[sda2], 'scl_oen') != scl_post_val:
            return (False, trace[sda2]['edge'], 'SCL did not remain in the post-release value at the SDA release (SDA second transition)')

        # verify cmd_ack asserted (rising) at end (normalized closes on cmd_ack==1)
        if trace[end]['outputs'].get('cmd_ack') != 1:
            # this should not happen because window closed on cmd_ack==1, but guard anyway
            return (False, trace[end]['edge'], 'window did not close with cmd_ack==1')
        prev_cmd_ack = trace[end-1]['outputs'].get('cmd_ack') if end-1 >= 0 else None
        if prev_cmd_ack == 1:
            # cmd_ack already high before the asserted completion; requirement speaks of asserting cmd_ack -> expect a rising event
            return (False, trace[end]['edge'], 'cmd_ack was already asserted before the sequence completed; no rising assertion observed at end')

        # If all checks passed for this window, report success for this attempt; continue to ensure no failing attempt earlier
        # return success keyed to the cmd_ack edge for localisation
        return (True, trace[end]['edge'], 'STOP sequence observed in order and cmd_ack asserted (localized at edge {})'.format(trace[end]['edge']))

    # If we fell through, no decisive completed window was found
    return (None, None, 'no decisive completed STOP activation')

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    # helper: predicate that a row's outputs/inputs match all items in `cond`
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    # any-of-alternatives: each alt is a dict that must hold together
    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # The surrounding text shows: "busy is 1 while the bit-level READ sequence is in progress; ... until cmd_ack".
    opens = _holds({"busy": 1})
    until_pred = _any([{"cmd_ack": 1}])

    # activation.aborts_on from the normalized block: al, nReset==0, rst==1
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])

    # effect_follows was false in the normalized activation: the expectation may hold at the activation row
    follows = False

    # Open windows while busy==1, close when cmd_ack becomes true, but abort on the listed aborts.
    windows = after(trace, opens, until=until_pred, aborts=aborts)

    if not windows:
        return (None, None, "the READ bit-level command sequence never ran (no busy==1 windows found)")

    # The obligation is to assert cmd_ack when the sequence completes; this is a required response, so strong=True.
    verdicts = [eventually(w, lambda r: r["outputs"].get("cmd_ack") == 1,
                          strong=True, after_activation=follows)
                for w in windows]

    return worst(verdicts)

def decide(trace):
    # windows are the arbitration-checking periods: busy==1 and sda_oen==1
    # aborts_on: nReset == 0 or rst == 1 (from normalized.activation.aborts_on)
    from specflow.refmodel.temporal import after, eventually, worst, TO_END

    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    opens = _holds({"busy": 1, "sda_oen": 1})
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    # effect_follows is false (from normalized.activation.effect_follows)
    follows = False

    # normalized.activation.until is empty -> window is co-extensive with activation
    windows = after(trace, opens, until=TO_END, aborts=aborts)
    if not windows:
        return (None, None, "arbitration-checking (busy==1 & sda_oen==1) never occurred")

    # collect windows where the antecedent was observed: sda_i == 0 while released
    relevant_windows = []
    for w in windows:
        saw_low = any((r["inputs"].get("sda_i") == 0) for r in w.rows)
        if saw_low:
            relevant_windows.append(w)

    if not relevant_windows:
        return (None, None, "no occurrence of SDA observed low while controller had released SDA during arbitration-check windows")

    verdicts = [eventually(w, lambda r: r["outputs"].get("al") == 1,
                           strong=True,
                           after_activation=follows)
                for w in relevant_windows]
    return worst(verdicts)

def decide(trace):
    # Decide REQ-0093: on arbitration lost (al==1) both scl_oen and sda_oen
    # must be deasserted (released/high == 1). We only observe declared ports.

    def outs(row):
        return row.get('outputs', {})

    def released(row):
        o = outs(row)
        return o.get('scl_oen') == 1 and o.get('sda_oen') == 1

    n = len(trace)
    windows = []  # list of (start_idx, end_idx) inclusive where al==1
    i = 0
    while i < n:
        if outs(trace[i]).get('al') == 1:
            start = i
            j = i
            # advance j while al remains asserted; do not use a fixed-offset lookahead
            while j < n and outs(trace[j]).get('al') == 1:
                j += 1
            end = j - 1
            windows.append((start, end))
            i = j
        else:
            i += 1

    if not windows:
        # activation never occurred in this trace
        return (None, None, 'arbitration lost (al==1) was not observed in this trace')

    # For each arbitration window, require that at SOME row in the window both outputs are released.
    # This is an obligation: absence inside the arbitration window is a violation.
    for (s, e) in windows:
        found = False
        for k in range(s, e + 1):
            if released(trace[k]):
                found = True
                break
        if not found:
            # Fail localized to the opening edge of the arbitration window
            return (False, trace[s]['edge'], f'scl_oen or sda_oen not released in arbitration window starting at edge {trace[s]["edge"]}')

    # All arbitration windows showed the lines released at least once
    return (True, None, f'all {len(windows)} arbitration window(s) observed scl_oen and sda_oen released')

def decide(trace):
    # Verify that every observed cmd_ack assertion (outside reset) is exactly one clk cycle.
    # The requirement names a one-clock-cycle acknowledge; that phrase justifies the numeric bound used here.
    from specflow.refmodel.temporal import runs

    # Find the starts of all runs where cmd_ack == 1 (any length >= 1).
    starts = runs(trace, 'cmd_ack', value=1, at_least=1)

    # Filter out occurrences that begin while reset/abort is active (nReset==0 or rst==1).
    valid = []
    for e in sorted(starts):
        row = next((r for r in trace if r['edge'] == e), None)
        if row is None:
            continue
        # aborts_on in the normalized form: nReset == 0 or rst == 1
        if row['inputs'].get('nReset', 1) == 0 or row['inputs'].get('rst', 0) == 1:
            # This occurrence is aborted by reset; ignore it.
            continue
        valid.append(row)

    # If there were no non-aborted cmd_ack assertions, the activation was not exercised here.
    if not valid:
        return (None, None, "no cmd_ack pulse was observed outside reset; the command-completion activation did not occur in this trace")

    # Check each observed non-aborted pulse lasts exactly one clock edge (row['held'] == 1).
    for row in valid:
        if row.get('held', 1) != 1:
            return (False, row['edge'], "cmd_ack pulse started at edge {} and lasted {} edges; requirement: 'One-clock-cycle command-complete acknowledge. It is asserted for one `clk` cycle when the current bit-level START, STOP, READ, or WRITE command finishes.'".format(row['edge'], row.get('held', 1)))

    # All observed pulses were single-clock as required.
    return (True, None, "{} cmd_ack pulse(s) observed outside reset and each lasted exactly one clk as required".format(len(valid)))

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst, TO_END

    # helper: check a row against a dict of port==value predicates
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # normalized activation pieces (transcribed):
    # inputs {"ena":1}, opens_on [{"scl_i":1, "sda_i":"rise"}], aborts_on [{"nReset":0}, {"rst":1}], effect_follows=false

    # Find sda rising edges in the trace
    sda_rises = edges(trace, "sda_i", "rise")

    # opening predicate: the sda rise happened at this row, and scl_i==1 and ena==1
    def opens_pred(row):
        return (
            row["edge"] in sda_rises
            and row["inputs"].get("scl_i") == 1
            and row["inputs"].get("ena") == 1
        )

    # aborts: reset conditions from activation.aborts_on
    aborts_pred = _any([{"nReset": 0}, {"rst": 1}])

    # build windows. activation.until was empty in the normalized form -> co-extensive;
    # pass TO_END so the window covers the activation's extent.
    windows = after(trace, opens_pred, until=TO_END, aborts=aborts_pred)

    # effect_follows is false in the normalized block, so evaluate at the activation row
    follows = False

    # expectation: al is driven high at that instant
    def al_high(r):
        return r["outputs"].get("al") == 1

    verdicts = [eventually(w, al_high, strong=True, after_activation=follows) for w in windows]
    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, throughout, worst

    # Helper: predicate that a row matches all (port==value) pairs.
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    # Helper: list-of-alternatives -> predicate (any alternative matches)
    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Transcribed from normalized activation:
    # opens_on: [{'sda_oen': 0}]
    opens = _holds({"sda_oen": 0})
    # aborts_on: [{'nReset': 0}, {'rst': 1}]
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    # effect_follows was false in the normalized block => evaluate at the
    # activation row as well.
    follows = False

    # The activation is co-extensive (until == [] in normalized), so we
    # close windows only when the activation stops or the trace ends.
    windows = after(trace, opens, until=TO_END, aborts=aborts)

    # Expectation: sda_o is 0 throughout each activation window.
    checks = [throughout(w, lambda r: r['outputs'].get('sda_o') == 0,
                         after_activation=follows)
              for w in windows]
    return worst(checks)

def decide(trace):
    # Check the synchronous-reset event(s): any row where rst==1 that begins a run
    # of rst being asserted is treated as the synchronous reset activation. The
    # normalized requirement has effect_follows=false so the outputs are sampled
    # at that activation row itself.
    if not trace:
        return (None, None, 'empty trace')

    def rst_at(r):
        return r.get('inputs', {}).get('rst') == 1

    # ports we are allowed to check (the requirement names them as being "cleared")
    cleared_ports = ['cmd_ack', 'busy', 'al', 'dout']

    activations = []  # rows where a rst activation opens (first row with rst==1)
    for i, r in enumerate(trace):
        if rst_at(r) and (i == 0 or not rst_at(trace[i-1])):
            activations.append(r)

    if not activations:
        return (None, None, 'the activation never occurred: rst was not observed asserted high')

    # Check each activation row for the cleared outputs == 0. We cannot assert
    # numeric reset values for bus-drive outputs (scl_o, sda_o, scl_oen, sda_oen)
    # because the specification does not give their encoding here.
    for act in activations:
        bad = []
        for p in cleared_ports:
            val = act.get('outputs', {}).get(p)
            # If the port is missing in the outputs dict treat it as unknown -> fail
            if val is None:
                bad.append((p, None))
            else:
                # 'cleared' in the text means de-asserted -> numeric 0
                if val != 0:
                    bad.append((p, val))
        if bad:
            details = ', '.join(f"{p}={v}" for p, v in bad)
            return (False, act.get('edge'), f"on synchronous reset (rst asserted) the requirement said these outputs be 'cleared' but got: {details}")

    # All activations showed cleared command/flag/data outputs.
    first_edge = activations[0].get('edge')
    return (True, first_edge, f"all {len(activations)} synchronous-reset activation(s) drove cleared outputs (cmd_ack,busy,al,dout)=0 as required")

def decide(trace):
    from specflow.refmodel.temporal import after, sequence, pulse, worst, TO_END

    # predicate builder for row-level conjunctions of port==value
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation and closing predicates transcribed from normalized block
    applies = _holds({"cmd": 2, "ena": 1})
    closes = _any([{"cmd_ack": 1}])
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])

    # The normalized block says effect_follows = true for this activation
    follows = True

    # open windows for each WRITE activation, closed by cmd_ack==1 (or aborted)
    windows = after(trace, applies, until=closes, aborts=aborts)

    # predicates for the scl_oen sequence: release (1) then drive-low (0)
    def scl_released(r):
        return r["outputs"].get("scl_oen") == 1

    def scl_driven_low(r):
        return r["outputs"].get("scl_oen") == 0

    # For each window we require the sequence (scl_oen==1) then (scl_oen==0)
    # and also that cmd_ack pulses (width=1, active=1) in the window.
    # This sequence is an obliged response, so strong=True is passed so that
    # running out of trace without the follow-up is a failure.
    per_window_verdicts = []
    for w in windows:
        seq_v = sequence(w, scl_released, scl_driven_low, after_activation=follows, strong=True)
        pulse_v = pulse(w, "cmd_ack", width=1, active=1, after_activation=follows)
        per_window_verdicts.append(worst([seq_v, pulse_v]))

    return worst(per_window_verdicts)

def decide(trace):
    # Activation: inputs.cmd == 2 and inputs.ena == 1 (from normalized block).
    # Aborts: inputs.nReset == 0 or inputs.rst == 1 (from normalized block).
    if not trace:
        return (None, None, 'empty trace')

    # Find contiguous windows where activation holds
    windows = []
    i = 0
    while i < len(trace):
        r = trace[i]
        if r['inputs'].get('cmd') == 2 and r['inputs'].get('ena') == 1:
            start = i
            i += 1
            while i < len(trace) and trace[i]['inputs'].get('cmd') == 2 and trace[i]['inputs'].get('ena') == 1:
                i += 1
            end = i - 1
            windows.append((start, end))
        else:
            i += 1

    if not windows:
        return (None, None, 'the STOP activation (cmd==2 && ena==1) never occurred')

    any_unknown = False
    # Evaluate each window; worst() semantics: any False wins, otherwise any Unknown, else True
    for (s, e) in windows:
        # Check for aborts inside the window
        aborted_edge = None
        for k in range(s, e + 1):
            if trace[k]['inputs'].get('nReset') == 0 or trace[k]['inputs'].get('rst') == 1:
                aborted_edge = trace[k]['edge']
                break
        if aborted_edge is not None:
            any_unknown = True
            # this window is undecidable; continue to see if other windows fail
            continue

        # Find first row in the window where sda_oen == 0 and first where scl_oen == 1
        sda_idx = None
        scl_idx = None
        for k in range(s, e + 1):
            if sda_idx is None and trace[k]['outputs'].get('sda_oen') == 0:
                sda_idx = k
            if scl_idx is None and trace[k]['outputs'].get('scl_oen') == 1:
                scl_idx = k
            if sda_idx is not None and scl_idx is not None:
                break

        # Apply ordering rules
        if sda_idx is None and scl_idx is None:
            # obligation expected the FSM to perform actions but neither was observed
            return (False, trace[s]['edge'], 'during STOP neither sda_oen==0 nor scl_oen==1 were observed')
        if sda_idx is None and scl_idx is not None:
            # SCL released without observed SDA assertion beforehand -> violation
            return (False, trace[scl_idx]['edge'], 'scl_oen==1 observed before any sda_oen==0 in the STOP window')
        if sda_idx is not None and scl_idx is None:
            # SDA was (or became) low but SCL release never observed -> violation (obligation)
            return (False, trace[e]['edge'], 'sda_oen==0 observed but scl_oen==1 not observed before STOP window ended')

        # both observed
        if sda_idx < scl_idx:
            # correct ordering: SDA driven low (0) first, then SCL released (1)
            return (True, trace[scl_idx]['edge'], 'sda_oen==0 observed at edge %d before scl_oen==1 at edge %d' % (trace[sda_idx]['edge'], trace[scl_idx]['edge']))
        if sda_idx == scl_idx:
            # both appear first on same row: ordering not observable -> unknown
            any_unknown = True
            continue
        # else sda_idx > scl_idx: SCL released before SDA driven low -> violation
        return (False, trace[scl_idx]['edge'], 'scl_oen==1 observed at edge %d before any sda_oen==0 (edge %d)' % (trace[scl_idx]['edge'], trace[sda_idx]['edge']))

    # No window produced a definitive failure; return Unknown if any window was undecidable
    if any_unknown:
        return (None, None, 'one or more STOP windows were aborted or provided no ordering evidence')
    # If we reach here, there were windows but none produced a decisive event (should not happen)
    return (None, None, 'no decisive result')

from specflow.refmodel.temporal import after, edges, TO_END, pulse, worst

def decide(trace):
    # Helpers to build predicates from normalized-style lists/dicts
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # We recognise each command-completion by a rising edge on the observable
    # cmd_ack and then require that that assertion is a single-state pulse.
    rises = edges(trace, "cmd_ack", "rise")

    # If there are no rises, the activation (command completion) never occurred
    # in this trace: return UNKNOWN rather than a failure.
    if not rises:
        return (None, None, "no cmd_ack rising edges observed; the command-completion activation did not occur in this trace")

    # Abort predicates transcribed from normalized.activation.aborts_on
    aborts_pred = _any([{"nReset": 0}, {"rst": 1}])

    # Build windows that open on each cmd_ack rise and run to the end (we check
    # the pulse beginning at the activation row). Allow overlapping windows so
    # multiple completions in one trace are each checked separately.
    follows = False  # normalized.activation.effect_follows
    windows = after(trace, lambda r: r["edge"] in rises, until=TO_END, aborts=aborts_pred, overlap=True)

    # For each window, require exactly one pulse of width 1 on cmd_ack starting
    # at the activation (after_activation=follows). pulse enforces rise then fall
    # one state later, which is what "exactly one clk cycle" means here.
    results = [pulse(w, "cmd_ack", width=1, active=1, after_activation=follows) for w in windows]

    return worst(results)

def decide(trace):
    # Transcribed from the normalized activation:
    # activation.inputs = {"ena": 1}
    # activation.until = []  (co-extensive -> window runs to end while ena==1)
    # activation.aborts_on = [{"nReset": 0}, {"rst": 1}]
    from specflow.refmodel.temporal import after, eventually, TO_END, worst

    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Open windows while ena == 1; they run to the end of trace (co-extensive)
    opens = _holds({"ena": 1})
    aborts = _any([{"nReset": 0}, {"rst": 1}])
    windows = after(trace, opens, until=TO_END, aborts=aborts)

    # The obligation: cmd_ack must be asserted (driven high) when the read-bit
    # completes. This is an active response the DUT must produce, so require it
    # eventually (strong=True). effect_follows was false in the normalization,
    # so allow the expectation to hold at the activation row.
    follows = False
    def holds_cmd_ack_high(row):
        return row["outputs"].get("cmd_ack") == 1

    verdicts = [eventually(w, holds_cmd_ack_high, strong=True, after_activation=follows)
                for w in windows]
    return worst(verdicts)

def decide(trace):
    # Find contiguous windows where reset is asserted (nReset==0 or rst==1).
    def is_reset_row(r):
        inp = r.get('inputs', {})
        return inp.get('nReset') == 0 or inp.get('rst') == 1

    windows = []
    cur = None
    for r in trace:
        if is_reset_row(r):
            if cur is None:
                cur = [r]
            else:
                cur.append(r)
        else:
            if cur is not None:
                windows.append(cur)
                cur = None
    if cur is not None:
        windows.append(cur)

    if not windows:
        return (None, None, 'no reset activation seen (no nReset==0 or rst==1 in trace)')

    # Expected reset values on declared outputs
    expected = {
        'scl_oen': 1,
        'sda_oen': 1,
        'cmd_ack': 0,
        'al': 0,
        'busy': 0,
    }

    # Check each window throughout: every row in the window must hold the expected levels.
    for w in windows:
        for r in w:
            outs = r.get('outputs', {})
            for port, exp in expected.items():
                val = outs.get(port)
                # If the port is missing from the outputs dict treat as unknown (violation of observable contract);
                # but use None to make the detail clear.
                if val != exp:
                    detail = (f"reset window violated at edge {r.get('edge')}: port {port} == {val!r},"
                              f" expected {exp} while reset held")
                    return (False, r.get('edge'), detail)
    # All windows held the reset values
    first_edge = windows[0][0].get('edge')
    return (True, first_edge, f"reset observed in {len(windows)} window(s); declared outputs held required reset values throughout (checked ports: {', '.join(sorted(expected.keys()))})")

def decide(trace):
    # Activation predicate transcribed from the normalized block:
    def _activation(row):
        inp = row.get('inputs', {})
        return (inp.get('ena') == 1 and inp.get('nReset') == 1
                and inp.get('rst') == 0 and inp.get('sda_i') == 0)

    def _is_abort(row):
        inp = row.get('inputs', {})
        return inp.get('nReset') == 0 or inp.get('rst') == 1

    n = len(trace)
    i = 0
    windows = []  # list of (start_index, open_edge, rows, aborted)
    while i < n:
        if _activation(trace[i]):
            start = i
            open_edge = trace[i]['edge']
            j = i
            aborted = False
            # window runs while the activation predicate holds, per normalization
            while j < n and _activation(trace[j]):
                if _is_abort(trace[j]):
                    aborted = True
                    break
                j += 1
            # collect the rows that belong to this activation (co-extensive)
            rows = trace[start:j]
            windows.append((start, open_edge, rows, aborted))
            # resume scanning after this activation ended
            i = j
        else:
            i += 1

    if not windows:
        return (None, None, 'the activation never occurred: no row with ena==1, nReset==1, rst==0 and sda_i==0')

    verdicts = []
    # Evaluate each window: aborted -> Unknown (None); non-aborted but no al -> False; otherwise True
    for start, open_edge, rows, aborted in windows:
        if aborted:
            verdicts.append((None, open_edge, 'activation aborted (nReset==0 or rst==1)'))
            continue
        # obligation: al must be asserted while the activation holds (may be at the activation row)
        saw_al = None
        for r in rows:
            if r.get('outputs', {}).get('al') == 1:
                saw_al = r
                break
        if saw_al is None:
            verdicts.append((False, open_edge, 'al was not asserted during this arbitration-check activation'))
        else:
            verdicts.append((True, saw_al['edge'], 'al asserted during arbitration-check'))

    # worst: any False -> report first False; else any True -> report first True; else any Unknown -> return Unknown
    for v, edge, detail in verdicts:
        if v is False:
            return (False, edge, detail)
    for v, edge, detail in verdicts:
        if v is True:
            return (True, edge, detail)
    # only unknowns remain
    return (None, verdicts[0][1], verdicts[0][2])

def decide(trace):
    # activation: applies at all times; if no rows, report unknown
    if not trace:
        return (None, None, 'the activation never occurred: no rows to inspect')

    # Check that scl_o and sda_o are 0 in every sampled state (continuously driven 0)
    for row in trace:
        edge = row.get('edge')
        outputs = row.get('outputs', {})

        # read only declared outputs
        scl_o = outputs.get('scl_o')
        sda_o = outputs.get('sda_o')

        if scl_o is None:
            return (None, edge, 'trace row missing declared output "scl_o"')
        if sda_o is None:
            return (None, edge, 'trace row missing declared output "sda_o"')

        if scl_o != 0:
            return (False, edge, f'scl_o != 0 at edge {edge}; requirement mandates continuous logic 0 drive')
        if sda_o != 0:
            return (False, edge, f'sda_o != 0 at edge {edge}; requirement mandates continuous logic 0 drive')

    # All rows show scl_o==0 and sda_o==0. We cannot observe external pull-ups here,
    # so the "active-low" effect of scl_oen/sda_oen on the external bus is not decidable
    # from the declared ports; do not assert it. Report success with no particular edge.
    return (True, None, f'all {len(trace)} sampled row(s) show scl_o==0 and sda_o==0; enable semantics not verifiable from these ports')

from specflow.refmodel.temporal import after, WHILE_ACTIVE, throughout, worst

# Decide signature as required by the framework
def decide(trace):
    # predicate builder: a condition is a dict of port->value, tested against
    # outputs first then inputs (as per guidance)
    def _holds(cond):
        def p(row):
            return all(
                (row['outputs'].get(k, row['inputs'].get(k)) == v)
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation: cmd == 3 and ena == 1 (READ command active)
    applies = _holds({'cmd': 3, 'ena': 1})
    # Abort conditions taken from normalized.activation.aborts_on
    aborts = _any([{'nReset': 0}, {'rst': 1}])

    # Open a window for the duration of the activation (co-extensive)
    windows = after(trace, applies, until=WHILE_ACTIVE, aborts=aborts)

    # Expectation: sda_oen is driven high (released) throughout the activation
    def sda_released(r):
        return r['outputs'].get('sda_oen') == 1

    follows = False  # normalized.activation.effect_follows

    return worst([throughout(w, sda_released, after_activation=follows)
                  for w in windows])

def decide(trace):
    # Temporal helpers provided by the refmodel environment
    from specflow.refmodel.temporal import after, edges, throughout, worst

    # Helpers to build predicates from normalized-style dict lists
    def _holds(cond):
        def p(row):
            # cond keys may refer to inputs or outputs; check both
            for k, v in cond.items():
                if row["outputs"].get(k, row["inputs"].get(k)) != v:
                    return False
            return True
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Build the opening predicate: sda_i FALL while scl_i == 1
    fell = edges(trace, "sda_i", "fall")
    def opens(r):
        return (r["edge"] in fell) and (r["inputs"].get("scl_i") == 1)

    # Build the closing predicate: sda_i RISE while scl_i == 1
    rose = edges(trace, "sda_i", "rise")
    def closes(r):
        return (r["edge"] in rose) and (r["inputs"].get("scl_i") == 1)

    # Abort conditions from normalized activation: nReset==0 OR rst==1
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    # Open windows on the START-shaped edge, close on the STOP-shaped one,
    # respect aborts. The normalized activation sets effect_follows = True.
    follows = True
    windows = after(trace, opens, until=closes, aborts=aborts)

    # For each window, busy must be asserted (busy == 1) throughout the window
    def busy_high(row):
        return row["outputs"].get("busy") == 1

    verdicts = [throughout(w, busy_high, after_activation=follows) for w in windows]
    return worst(verdicts)

