def decide(trace):
    """
    Decide REQ-0038. The obligation refers to internal signal `slave_wait` (and
    internal filtered SCL `sSCL`) which are not exported on any declared
    output. We can only recognise the activation (master releases SCL while
    bus SCL is low) using declared ports scl_oen (output) and scl_i (input).

    Behaviour:
      - Find contiguous windows where scl_oen == 1 and scl_i == 0.
      - If no such window exists, return (None, None, 'activation never occurred').
      - If at least one window exists, return UNKNOWN (ok=None) with the edge
        where the first activation opened and a message that the expectation
        cannot be observed because `slave_wait` is internal.
    """
    # helper: predicate for the activation's opens_on {"scl_i":0, "scl_oen":1}
    def _active_row(r):
        # scl_i is an input, scl_oen is an output (declared ports only)
        if r.get('inputs', {}).get('scl_i') != 0:
            return False
        if r.get('outputs', {}).get('scl_oen') != 1:
            return False
        return True

    # find contiguous runs of rows where _active_row is True
    windows = []  # list of (start_index, start_edge, rows)
    cur_rows = None
    for idx, r in enumerate(trace):
        if _active_row(r):
            if cur_rows is None:
                cur_rows = {'start_idx': idx, 'start_edge': r.get('edge'), 'rows': [r]}
            else:
                cur_rows['rows'].append(r)
        else:
            if cur_rows is not None:
                windows.append(cur_rows)
                cur_rows = None
    if cur_rows is not None:
        windows.append(cur_rows)

    if not windows:
        return (None, None, 'activation never occurred: no row with scl_oen==1 while scl_i==0')

    first = windows[0]
    edge = first['start_edge']
    detail = (
        'requirement refers to internal signal `slave_wait` (and internal `sSCL`) which are not in the declared outputs; '
        'activation detected (scl_oen==1 with scl_i==0) at edge {}'.format(edge)
        + "; cannot observe or decide whether `slave_wait` was asserted"
    )
    # Unknown / not decidable from the trace because the expected signal is internal
    return (None, edge, detail)

