def decide(trace):
    # Activation: inputs.cmd == 2 and inputs.ena == 1 (from normalized block).
    # Aborts: inputs.nReset == 0 or inputs.rst == 1 (from normalized block).
    if not trace:
        return (None, None, 'empty trace')

    # Find contiguous windows where activation holds
    windows = []
    i = 0
    while i < len(trace):
        r = trace[i]
        if r['inputs'].get('cmd') == 2 and r['inputs'].get('ena') == 1:
            start = i
            i += 1
            while i < len(trace) and trace[i]['inputs'].get('cmd') == 2 and trace[i]['inputs'].get('ena') == 1:
                i += 1
            end = i - 1
            windows.append((start, end))
        else:
            i += 1

    if not windows:
        return (None, None, 'the STOP activation (cmd==2 && ena==1) never occurred')

    any_unknown = False
    # Evaluate each window; worst() semantics: any False wins, otherwise any Unknown, else True
    for (s, e) in windows:
        # Check for aborts inside the window
        aborted_edge = None
        for k in range(s, e + 1):
            if trace[k]['inputs'].get('nReset') == 0 or trace[k]['inputs'].get('rst') == 1:
                aborted_edge = trace[k]['edge']
                break
        if aborted_edge is not None:
            any_unknown = True
            # this window is undecidable; continue to see if other windows fail
            continue

        # Find first row in the window where sda_oen == 0 and first where scl_oen == 1
        sda_idx = None
        scl_idx = None
        for k in range(s, e + 1):
            if sda_idx is None and trace[k]['outputs'].get('sda_oen') == 0:
                sda_idx = k
            if scl_idx is None and trace[k]['outputs'].get('scl_oen') == 1:
                scl_idx = k
            if sda_idx is not None and scl_idx is not None:
                break

        # Apply ordering rules
        if sda_idx is None and scl_idx is None:
            # obligation expected the FSM to perform actions but neither was observed
            return (False, trace[s]['edge'], 'during STOP neither sda_oen==0 nor scl_oen==1 were observed')
        if sda_idx is None and scl_idx is not None:
            # SCL released without observed SDA assertion beforehand -> violation
            return (False, trace[scl_idx]['edge'], 'scl_oen==1 observed before any sda_oen==0 in the STOP window')
        if sda_idx is not None and scl_idx is None:
            # SDA was (or became) low but SCL release never observed -> violation (obligation)
            return (False, trace[e]['edge'], 'sda_oen==0 observed but scl_oen==1 not observed before STOP window ended')

        # both observed
        if sda_idx < scl_idx:
            # correct ordering: SDA driven low (0) first, then SCL released (1)
            return (True, trace[scl_idx]['edge'], 'sda_oen==0 observed at edge %d before scl_oen==1 at edge %d' % (trace[sda_idx]['edge'], trace[scl_idx]['edge']))
        if sda_idx == scl_idx:
            # both appear first on same row: ordering not observable -> unknown
            any_unknown = True
            continue
        # else sda_idx > scl_idx: SCL released before SDA driven low -> violation
        return (False, trace[scl_idx]['edge'], 'scl_oen==1 observed at edge %d before any sda_oen==0 (edge %d)' % (trace[scl_idx]['edge'], trace[sda_idx]['edge']))

    # No window produced a definitive failure; return Unknown if any window was undecidable
    if any_unknown:
        return (None, None, 'one or more STOP windows were aborted or provided no ordering evidence')
    # If we reach here, there were windows but none produced a decisive event (should not happen)
    return (None, None, 'no decisive result')

