def decide(trace):
    # Activation: module operating (not held in reset)
    activation_row = None
    for r in trace:
        if r.get('inputs', {}).get('nReset') == 1 and r.get('inputs', {}).get('rst') == 0:
            activation_row = r
            break
    if activation_row is None:
        # activation never occurred in this trace
        return (None, None, 'the module was held in reset for the entire trace; activation never occurred')

    # Inspect declared outputs at the activation row to ensure we read the design boundary
    declared_outputs = ['cmd_ack', 'busy', 'al', 'dout', 'scl_o', 'scl_oen', 'sda_o', 'sda_oen']
    outs = activation_row.get('outputs', {})
    observed = {p: outs.get(p) for p in declared_outputs if p in outs}

    # The obligation is about internal signals (sSCL, sSDA) that are not present
    # in declared outputs. Per the contract rules we must not read internal signals
    # or invent an encoding or mapping to external ports. Therefore we must
    # abstain (ok=None) while pointing at the activation edge so a human can
    # inspect the design if desired.
    detail = ('cannot decide: sSCL and sSDA are internal signals not present in declared outputs; '
              'inspected declared outputs at activation row: ' +
              (', '.join(f"{k}={v}" for k, v in observed.items()) if observed else 'none'))
    return (None, activation_row.get('edge'), detail)

