def decide(trace):
    # REQ-0060: the obligation is only the list-item marker '11.' and states no
    # behavioural or interface requirement. There is nothing observable to check
    # on the declared outputs, so the only correct result is to abstain.
    # Read one declared output ('busy') to show declared ports are present, but
    # do not assert any effect based on it.
    if not trace:
        return (None, None, "REQ-0060: trace empty; no activation and no observable behaviour specified")
    last_busy = trace[-1]['outputs'].get('busy')
    return (None, None, f"REQ-0060: no observable behaviour specified; touched declared output 'busy' (value={last_busy})")

